import json
from fastmcp import FastMCP
from pydantic import BaseModel

mcp = FastMCP('company-brain')
SNIP = 300

class Item(BaseModel):
    id: str
    title: str
    url: str
    text: str | None = None

class SearchOut(BaseModel):
    results: list[Item]

def _both(model: BaseModel):
    # same payload twice: structured and as JSON text, as ChatGPT expects
    return model.model_dump(), json.dumps(model.model_dump())

@mcp.tool(annotations={'readOnlyHint': True})
async def search(query: str) -> SearchOut:
    user = current_user()
    hits = await retrieval.search(user, query, limit=20)
    items = []
    for h in hits:
        if not h.url:                      # no url, no citation: drop it
            metrics.inc('search_dropped_no_url')
            continue
        items.append(Item(id=h.pointer_id, title=h.title, url=h.url, text=(h.snippet or '')[:SNIP]))
    return SearchOut(results=items)

@mcp.tool(annotations={'readOnlyHint': True})
async def fetch(id: str) -> dict:
    doc = await hydrator.fetch(current_user(), id)    # rechecks access with the user token
    if doc is None:
        raise ToolError('not_found')
    return {'id': id, 'title': doc.title, 'text': doc.text[:CAP], 'url': doc.url, 'metadata': {'truncated': len(doc.text) > CAP}}

