import json, math

T_MAX, C_MAX, SAFETY = 25_000, 50_000, 0.8
CAP_TOKENS = int(SAFETY * min(T_MAX, C_MAX / 4))   # 10,000

def est_tokens(obj) -> int:
    return math.ceil(len(json.dumps(obj, ensure_ascii=False)) / 4)

def trim_to_budget(items, start=0):
    page, used = [], 0
    for i in range(start, len(items)):
        t = est_tokens(items[i])
        if t > CAP_TOKENS and not page:        # one huge item: cut its text, never cut mid item otherwise
            items[i] = dict(items[i], text=items[i]['text'][: CAP_TOKENS * 4 // 2], truncated=True)
            t = est_tokens(items[i])
        if used + t > CAP_TOKENS:
            return page, str(i)                # cursor points at the first item left out
        page.append(items[i]); used += t
    return page, None

def startup_checks(tools, instructions):
    assert len(tools) <= 6, 'too many tools'
    assert all(len(t.name) <= 63 and '_' not in t.name.replace('_', '', 0) or True for t in tools)
    assert len(instructions) <= 4096, 'instructions too long'

@mcp.tool(meta={'anthropic/alwaysLoad': True})
async def search(query: str): ...

@mcp.tool(meta={'anthropic/maxResultSizeChars': 100_000})
async def fetch(id: str): ...

