import ipaddress, httpx, yaml, json, pathlib

def fetch_ranges(url):
    r = httpx.get(url, timeout=10, follow_redirects=False)
    r.raise_for_status()
    return {str(ipaddress.ip_network(x.strip(), strict=False)) for x in parse_ranges(r.text)}

def refresh(sources_path, current_path):
    cfg = yaml.safe_load(open(sources_path))
    new = set(cfg.get('org_ranges', []))
    for s in cfg['sources']:
        new |= fetch_ranges(s['url'])          # a failing vendor raises: keep the old list
    cur_p = pathlib.Path(current_path)
    cur = set(json.loads(cur_p.read_text())) if cur_p.exists() else set()
    if not new:
        return 'rejected: empty list'
    if cur and (len(new) / len(cur) > 10 or len(cur) / len(new) > 10):
        return 'rejected: size changed more than 10x'   # guard against a bad parse
    cur_p.write_text(json.dumps(sorted(new)))
    pathlib.Path('edge/allowlist.caddy').write_text('remote_ip ' + ' '.join(sorted(new)) + '\n')
    return 'applied'

# Caddyfile (vendor_allowlist mode):
# brain.example.com {
#   @vendors { import allowlist.caddy }
#   handle /.well-known/* { reverse_proxy app:8000 }   # discovery stays public
#   handle @vendors { reverse_proxy app:8000 }
#   respond 403
# }

